36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.samples.petclinic.util.AddressNormalizer;
45	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
46	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Maximum number of owners a single city may contain; creating an owner in a city that
65	     *  already has this many owners is rejected with 409 Conflict. */
66	    private static final int MAX_OWNERS_PER_CITY = 50;
67	
68	    /** Maximum number of owners that may be created on a single day (by registration date); creating
69	     *  an owner once this many owners already carry today's registration date is rejected with
70	     *  429 Too Many Requests. */
71	    private static final int MAX_OWNERS_PER_DAY = 100;
72	
73	    /** When more than this many owners already carry today's registration date at creation time, the
74	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
75	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
76	
77	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
78	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final TelephoneNormalizer telephoneNormalizer;
89	
90	    private final HouseholdNormalizer householdNormalizer;
91	
92	    private final AddressNormalizer addressNormalizer;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper,
98	                                 TelephoneNormalizer telephoneNormalizer,
99	                                 HouseholdNormalizer householdNormalizer,
100	                                 AddressNormalizer addressNormalizer) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	        this.telephoneNormalizer = telephoneNormalizer;
106	        this.householdNormalizer = householdNormalizer;
107	        this.addressNormalizer = addressNormalizer;
108	    }
109	
110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
113	        Collection<Owner> owners;
114	        if (lastName != null) {
115	            owners = this.clinicService.findOwnerByLastName(lastName);
116	        } else {
117	            owners = this.clinicService.findAllOwners();
118	        }
119	        if (owners.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        HttpHeaders headers = new HttpHeaders();
139	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
140	        normalizeOwnerFields(owner);
141	        // Enforce the pre-persistence policies that can reject the new owner outright.
142	        rejectDisallowedOwnerCreation(owner);
143	        // Resolve the owner's household membership: assign the shared 'householdId' when the
144	        // request opts in and joins an existing household, and record the household size. This runs
145	        // before the identity-key check so that check sees the owner's final household id.
146	        applyHouseholdMembership(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
147	        // Reject the create when the owner's whole derived identity key (normalized telephone,
148	        // email and household id) already matches an existing owner. This single rule subsumes the
149	        // former separate telephone, email and household duplicate checks.
150	        rejectWhenIdentityInUse(owner);
151	        // Assign the remaining create-time derived fields (namesake count, customer code,
152	        // membership number and bulk-signup warning), each fixed at creation time.
153	        assignDerivedFields(owner);
154	        this.clinicService.saveOwner(owner);
155	        // Emit an audit line for the successful create, carrying the owner id, customer code and
156	        // registration date so the create can be traced from the dedicated AUDIT log.
157	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
158	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
159	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
160	        headers.setLocation(UriComponentsBuilder.newInstance()
161	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
162	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    /**
166	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
167	     * outright, in order, before any derived fields are assigned or the owner is saved. Each
168	     * independent rule lives in its own {@code rejectWhen...} guard and is applied here in order, so
169	     * the sequence of create-time rejections stays readable and a new rule is added as one more
170	     * guard. Grouping the rules here keeps {@link #addOwner} focused on the household, derived-field
171	     * and persistence steps. The single duplicate rule that rejects an owner whose whole identity
172	     * key matches an existing one is applied separately in {@link #rejectWhenIdentityInUse}, after
173	     * the household id has been resolved, because that key includes the household id.
174	     *
175	     * @param owner the newly mapped and normalized owner being created
176	     */
177	    private void rejectDisallowedOwnerCreation(Owner owner) {
178	        rejectWhenDailyLimitReached(owner);
179	        rejectWhenCityAtCapacity(owner);
180	    }
181	
182	    /**
183	     * Applies the household-membership rules for a newly normalized owner being created. It finds
184	     * the existing owners who share the owner's household (same last name and address, compared
185	     * case-insensitively with collapsed whitespace), then, using that single lookup: when the
186	     * request opts in via {@code sharesHousehold} and the owner joins an existing household, assigns
187	     * the new owner and every existing member the same stable {@code householdId}; and records the
188	     * owner's {@code householdSize}. Sharing a household is no longer a rejection on its own: a new
189	     * owner is rejected only when its whole identity key matches an existing owner (see
190	     * {@link #rejectWhenIdentityInUse}), and the household id resolved here is part of that key.
191	     *
192	     * @param owner           the newly mapped and normalized owner being created
193	     * @param sharesHousehold whether the request opted in to joining an existing household
194	     */
195	    private void applyHouseholdMembership(Owner owner, boolean sharesHousehold) {
196	        // Identify any existing owners who share a household (same last name and address,
197	        // compared case-insensitively with collapsed whitespace) with the owner being created.
198	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
199	        // When opting in and joining an existing household, assign the new owner and every
200	        // existing member the same stable household identifier derived from the last name and
201	        // address, so all owners of the household share one 'householdId'.
202	        if (sharesHousehold && !householdMembers.isEmpty()) {
203	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
204	            owner.setHouseholdId(householdId);
205	            for (Owner member : householdMembers) {
206	                if (!householdId.equals(member.getHouseholdId())) {
207	                    member.setHouseholdId(householdId);
208	                    this.clinicService.saveOwner(member);
209	                }
210	            }
211	        }
212	        // Record the size of this owner's household after this create, i.e. the number of owners
213	        // sharing this owner's 'householdId' once it is persisted. An owner that shares an existing
214	        // household counts the matched members plus itself; an owner without a shared household is a
215	        // household of one. Fixed at creation time.
216	        owner.setHouseholdSize(owner.getHouseholdId() == null ? 1 : householdMembers.size() + 1);
217	    }
218	
219	    /**
220	     * Assigns the create-time derived fields of a newly normalized owner whose household membership
221	     * has already been resolved: the namesake count, the per-city customer code, the membership
222	     * number derived from that customer code and the registration year, and the bulk-signup warning
223	     * flag. Each value is fixed at creation time and is independent of the others. Grouping them
224	     * here keeps {@link #addOwner} focused on the high-level create sequence.
225	     *
226	     * @param owner the owner being created, already normalized and with its household resolved
227	     */
228	    private void assignDerivedFields(Owner owner) {
229	        // Record how many existing owners already share this owner's first and last name
230	        // (compared case-insensitively) before this create, fixed at creation time.
231	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
232	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
233	        // per-city sequence equal to one more than the owners already in that city, fixed at
234	        // creation time.
235	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
236	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
237	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
238	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
239	        // Flag the create when more than 80 owners have already been created on this owner's
240	        // (adjusted business-day) registration date, fixed at creation time.
241	        owner.setBulkSignupWarning(
242	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
243	    }
244	
245	    /**
246	     * Rejects creating an owner whose whole derived identity key already matches an existing owner,
247	     * with 409 Conflict. The identity key ({@link Owner#getIdentityKey()}) joins the normalized
248	     * telephone, the email (or empty) and the household id (or empty), so this single rule replaces
249	     * the former separate telephone, email and household duplicate checks: two owners collide only
250	     * when their whole keys are equal, and members of one household with different telephones have
251	     * different keys and are both allowed.
252	     *
253	     * @param owner the owner being created, already normalized and with its household resolved
254	     */
255	    private void rejectWhenIdentityInUse(Owner owner) {
256	        String identityKey = owner.getIdentityKey();
257	        boolean inUse = this.clinicService.findAllOwners().stream()
258	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
259	        if (inUse) {
260	            throw new DuplicateIdentityException(
261	                "An owner with identity key " + identityKey + " already exists");
262	        }
263	    }
264	
265	    /**
266	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners already carry this
267	     * owner's adjusted business-day registration date, with 429 Too Many Requests.
268	     *
269	     * @param owner the owner being created
270	     */
271	    private void rejectWhenDailyLimitReached(Owner owner) {
272	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
273	            throw new DailyOwnerLimitExceededException(
274	                "The maximum number of owners that may be created today has already been reached");
275	        }
276	    }
277	
278	    /**
279	     * Rejects creating an owner when the owner's city already contains {@link #MAX_OWNERS_PER_CITY}
280	     * or more owners, with 409 Conflict.
281	     *
282	     * @param owner the owner being created
283	     */
284	    private void rejectWhenCityAtCapacity(Owner owner) {
285	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
286	            throw new CityCapacityExceededException(
287	                "The city " + owner.getCity() + " already contains the maximum number of owners");
288	        }
289	    }
290	
291	    /**
292	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
293	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
294	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
295	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
296	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
297	     * server's current date. Canonicalising the address here, before the household checks read it,
298	     * ensures duplicate detection and the shared household id both compare the normalized form.
299	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
300	     * duplicate, household and customer-code rules.
301	     *
302	     * @param owner the newly mapped owner to canonicalize
303	     */
304	    private void normalizeOwnerFields(Owner owner) {
305	        // Normalize the address on create so it is stored and returned in canonical form and every
306	        // later comparison (household duplicate detection and the shared household id) uses it.
307	        // A value that is blank after normalization is rejected with 400.
308	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
309	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
310	        // A value that cannot form a valid E.164 number, or whose national-number length is wrong
311	        // for its country code (+61 => 9 national digits, +1 => 10), is rejected with 400.
312	        owner.setTelephone(telephoneNormalizer.normalizeAndValidate(owner.getTelephone()));
313	        // Store the (already syntactically validated) email lower-cased so it is persisted and
314	        // returned in canonical form. A missing email is left untouched.
315	        owner.setEmail(normalizeEmail(owner.getEmail()));
316	        // Default the registration date to the server's current date when the client did not
317	        // supply one, then roll the effective date forward to a business day so a Saturday or
318	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
319	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
320	        // date-derived field (such as the membership number's year segment) and the per-day
321	        // create-limit are computed from.
322	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
323	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
324	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
325	    }
326	
327	    /**
328	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
329	     * following Monday, while a weekday is returned unchanged. Applied to the effective
330	     * registration date (whether supplied in the request or defaulted to the server date) so the
331	     * persisted registration date, every value derived from it and the per-day create-limit all
332	     * use the adjusted business day.
333	     *
334	     * @param date the effective registration date
335	     * @return the same date if it is a weekday, otherwise the following Monday
336	     */
337	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
338	        java.time.LocalDate adjusted = date;
339	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
340	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
341	            adjusted = adjusted.plusDays(1);
342	        }
343	        return adjusted;
344	    }
345	
346	    /**
347	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
348	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
349	     * syntactically valid address (rejecting anything else with 400).
350	     *
351	     * @param email the email value (may be {@code null})
352	     * @return the lower-cased email, or {@code null} if the input was {@code null}
353	     */
354	    private String normalizeEmail(String email) {
355	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
356	    }
357	
358	    /**
359	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
360	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
361	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
362	     * the owners already in that city (e.g. 'LON-SMI-0007').
363	     *
364	     * @param city     the owner's city
365	     * @param lastName the owner's last name
366	     * @return the formatted customer code
367	     */
368	    private String nextCustomerCode(String city, String lastName) {
369	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
370	            .toUpperCase(java.util.Locale.ROOT);
371	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
372	            .toUpperCase(java.util.Locale.ROOT);
373	        int sequence = countOwnersInCity(city) + 1;
374	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
375	    }
376	
377	    /**
378	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
379	     * fix the per-city sequence of an owner's customer code at creation time.
380	     *
381	     * @param city the city of the owner being created
382	     * @return the number of existing owners in a matching city
383	     */
384	    private int countOwnersInCity(String city) {
385	        return (int) this.clinicService.findAllOwners().stream()
386	            .filter(existing -> existing.getCity() != null
387	                && existing.getCity().equalsIgnoreCase(city))
388	            .count();
389	    }
390	
391	    /**
392	     * Counts the existing owners whose registration date is the given adjusted business day. Used
393	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
394	     * owners already carry that business day as their registration date.
395	     *
396	     * @param date the adjusted business-day registration date to match
397	     * @return the number of existing owners registered on that date
398	     */
399	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
400	        return (int) this.clinicService.findAllOwners().stream()
401	            .filter(existing -> date.equals(existing.getRegistrationDate()))
402	            .count();
403	    }
404	
405	    /**
406	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
407	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
408	     *
409	     * @param customerCode     the owner's customer code
410	     * @param registrationDate the owner's registration date
411	     * @return the formatted membership number
412	     */
413	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
414	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
415	    }
416	
417	    /**
418	     * Returns the existing owners who share the given household, i.e. have the same last name and
419	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
420	     * differing only in letter case or in incidental whitespace are treated as the same household.
421	     *
422	     * @param lastName the last name of the owner being created
423	     * @param address  the address of the owner being created
424	     * @return the existing owners with a matching last name and address (possibly empty)
425	     */
426	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
427	        String householdKey = householdNormalizer.householdKey(lastName, address);
428	        return this.clinicService.findAllOwners().stream()
429	            .filter(existing -> householdNormalizer
430	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
431	            .toList();
432	    }
433	
434	    /**
435	     * Counts the existing owners who share the given first and last name, compared
436	     * case-insensitively. Used to fix an owner's namesake count at creation time.
437	     *
438	     * @param firstName the first name of the owner being created
439	     * @param lastName  the last name of the owner being created
440	     * @return the number of existing owners with a matching first and last name
441	     */
442	    private int countNamesakes(String firstName, String lastName) {
443	        return (int) this.clinicService.findAllOwners().stream()
444	            .filter(existing -> existing.getFirstName() != null
445	                && existing.getFirstName().equalsIgnoreCase(firstName)
446	                && existing.getLastName() != null
447	                && existing.getLastName().equalsIgnoreCase(lastName))
448	            .count();
449	    }
450	
451	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
452	    @Override
453	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
454	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
455	        if (currentOwner == null) {
456	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
457	        }
458	        currentOwner.setAddress(ownerFieldsDto.getAddress());
459	        currentOwner.setCity(ownerFieldsDto.getCity());
460	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
461	        currentOwner.setLastName(ownerFieldsDto.getLastName());
462	        // Normalize the telephone to canonical E.164 form so it is stored and returned
463	        // consistently with create; an unformattable value is rejected with 400.
464	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
465	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
466	        this.clinicService.saveOwner(currentOwner);
467	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
468	    }
469	
470	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
471	    @Transactional
472	    @Override
473	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
474	        Owner owner = this.clinicService.findOwnerById(ownerId);
475	        if (owner == null) {
476	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
477	        }
478	        this.clinicService.deleteOwner(owner);
479	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
480	    }
481	
482	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
483	    @Override
484	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
485	        Owner owner = this.clinicService.findOwnerById(ownerId);
486	        if (owner == null) {
487	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
488	        }
489	        HttpHeaders headers = new HttpHeaders();
490	        Pet pet = petMapper.toPet(petFieldsDto);
491	        owner.setId(ownerId);
492	        pet.setOwner(owner);
493	        pet.getType().setName(null);
494	        this.clinicService.savePet(pet);
495	        PetDto petDto = petMapper.toPetDto(pet);
496	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
497	            .buildAndExpand(pet.getId()).toUri());
498	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
499	    }
500	
501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
504	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
505	        if (currentOwner != null) {
506	            Pet currentPet = this.clinicService.findPetById(petId);
507	            if (currentPet != null) {
508	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
509	                currentPet.setName(petFieldsDto.getName());
510	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
511	                this.clinicService.savePet(currentPet);
512	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
513	            }
514	        }
515	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
516	    }
517	
518	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
519	    @Override
520	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
521	        HttpHeaders headers = new HttpHeaders();
522	        Visit visit = visitMapper.toVisit(visitFieldsDto);
523	        Pet pet = new Pet();
524	        pet.setId(petId);
525	        visit.setPet(pet);
526	        this.clinicService.saveVisit(visit);
527	        VisitDto visitDto = visitMapper.toVisitDto(visit);
528	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
529	            .buildAndExpand(visit.getId()).toUri());
530	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
531	    }
532	
533	
534	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
535	    @Override
536	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
537	        Owner owner = this.clinicService.findOwnerById(ownerId);
538	        if (owner != null) {
539	            Pet pet = owner.getPet(petId);
540	            if (pet != null) {
541	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
542	            }
543	        }
544	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
545	    }
546	}
